package org.apache.commons.lang3.math;

import junit.framework.TestCase;

public class FractionBugOriginTest extends TestCase {

    public void testReducedFactory_int_int() {
        Fraction f = Fraction.getReducedFraction(Integer.MIN_VALUE, 2);
        assertEquals(Integer.MIN_VALUE / 2, f.getNumerator());
        assertEquals(1, f.getDenominator());
    }

    public void testReduce() {
        Fraction f = Fraction.getFraction(Integer.MIN_VALUE, 2);
        Fraction result = f.reduce();
        assertEquals(Integer.MIN_VALUE / 2, result.getNumerator());
        assertEquals(1, result.getDenominator());
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {
    public void testLang710() {
        try {
            String input = "&#03";
            String result = StringEscapeUtils.unescapeHtml4(input);
            // The reporter says it throws StringIndexOutOfBoundsException.
            // If it doesn't throw, we expect it to either leave it as is or unescape it,
            // but definitely not crash.
            assertEquals("&#03", result);
        } catch (StringIndexOutOfBoundsException e) {
            fail("Should not throw StringIndexOutOfBoundsException: " + e.getMessage());
        }
    }
}

package org.apache.commons.lang3;

import junit.framework.TestCase;

public class StringEscapeUtilsBugOriginTest extends TestCase {

    public void testEscapeXmlSupplementaryCharacters() {
        // A supplementary character: U+1D306 (TETRAGRAM FOR CENTRE)
        // In UTF-16, this is represented as \uD834\uDF06
        String supplementaryChar = "\uD834\uDF06";
        String escaped = StringEscapeUtils.escapeXml(supplementaryChar);

        // The bug is that it treats them as two separate characters.
        // Expected: "&#119558;" (decimal for 0x1D306)
        // Actual (buggy): "&#55348;&#57094;" (decimal for 0xD834 and 0xDF06)

        assertEquals("&#119558;", escaped);
    }
}
